using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class SceneTabsOperations
{
    private readonly AudioDocumentOperations _audioDocuments=new();private readonly AudioWorkspaceOperations _audioWorkspace=new();private readonly AudioEditSessionOperations _audioSessions=new();private readonly Expression _associationEqual=AssociationEqual();private static Expression AssociationEqual(){var expression=new Expression();expression.Parse("a == b",new[]{"a","b"});return expression;}
    public string association_path(string path){if(path.Length==0)return "";string normalized=ProjectSettings.GlobalizePath(path).Replace('\\','/').SimplifyPath();return OS.GetName()=="Windows"?normalized.ToLowerInvariant():normalized;}
    public string stored_scene_path(string path)=>path.Length==0?"":ProjectSettings.LocalizePath(ProjectSettings.GlobalizePath(path)).Replace('\\','/').SimplifyPath();
    public string audio_identity(Variant value)=>value.VariantType==Variant.Type.String?association_path(value.AsString()):value.VariantType==Variant.Type.Object&&value.AsGodotObject() is GodotObject resource?"embedded:"+resource.GetInstanceId():"";
    public int audio_document_index(TabBar owner,string id){if(id.Length==0)return -1;var documents=Documents(owner);for(int i=0;i<documents.Count;i++)if(documents[i].AsGodotDictionary().GetValueOrDefault("id","").AsString()==id)return i;return -1;}
    public int audio_scene_index_for_id(TabBar owner,string id){int index=audio_document_index(owner,id);return index>=0&&Kind(Documents(owner)[index].AsGodotDictionary())=="scene"?index:-1;}
    public RefCounted? audio_session_for_index(TabBar owner,int index){var documents=Documents(owner);if(index<0||index>=documents.Count||Kind(documents[index].AsGodotDictionary())!="audio")return null;var workspace=Workspace(owner,"audio");if(index==Active(owner)&&workspace!=null)return workspace.Get("session").As<RefCounted>();var value=documents[index].AsGodotDictionary().GetValueOrDefault("state",new Settings()).AsGodotDictionary().GetValueOrDefault("session");return value.VariantType==Variant.Type.Object?value.AsGodotObject() as RefCounted:null;}
    public int scene_index_for_association(TabBar owner,Settings association){string uid=association.GetValueOrDefault("scene_uid","").AsString();if(uid.Length==0)return -1;string path=association_path(association.GetValueOrDefault("scene_path","").AsString());int found=-1;var documents=Documents(owner);for(int i=0;i<documents.Count;i++){var candidate=documents[i].AsGodotDictionary();if(Kind(candidate)!="scene"||candidate.GetValueOrDefault("persistent_id","").AsString()!=uid)continue;if(path.Length>0&&association_path(candidate.GetValueOrDefault("path","").AsString())!=path)continue;if(found>=0)return -1;found=i;}return found;}
    private void EditAssociation(RefCounted session,string label,Settings association){bool nested=session.Get("_before").VariantType!=Variant.Type.Nil;_audioSessions.begin(session,label);session.Get("document").AsGodotObject().Set("scene_binding",association.Duplicate(true));if(!nested)_audioSessions.commit(session);}
    public void set_audio_scene_association(TabBar owner,string sourceId,string sceneId,string actorId){int sourceIndex=audio_document_index(owner,sourceId),sceneIndex=audio_scene_index_for_id(owner,sceneId);var session=audio_session_for_index(owner,sourceIndex);if(sceneIndex<0||session==null)return;var documents=Documents(owner);var destination=documents[sceneIndex].AsGodotDictionary();var association=new Settings{["version"]=1,["scene_uid"]=destination.GetValueOrDefault("persistent_id","").AsString(),["scene_path"]=stored_scene_path(destination.GetValueOrDefault("path","").AsString()),["actor_id"]=actorId};if(association["scene_uid"].AsString().Length==0)return;if(!_associationEqual.Execute(new Godot.Collections.Array{session.Get("document").AsGodotObject().Get("scene_binding"),association}).AsBool())EditAssociation(session,"Link audio to scene",association);documents[sourceIndex].AsGodotDictionary()["scene_id"]=sceneId;if(!destination.GetValueOrDefault("persistent_saved",false).AsBool())documents[sceneIndex].AsGodotDictionary()["dirty"]=true;if(sourceIndex==Active(owner))Workspace(owner,"audio")?.Call("set_scene_binding",true);refresh_titles(owner);}
    public void relocate_audio_associations(TabBar owner,string uid,string previous,string destination){if(uid.Length==0)return;string oldPath=association_path(previous),newPath=association_path(destination);var documents=Documents(owner);for(int i=0;i<documents.Count;i++){var session=audio_session_for_index(owner,i);if(session==null)continue;var association=session.Get("document").AsGodotObject().Get("scene_binding").AsGodotDictionary();if(association.GetValueOrDefault("scene_uid","").AsString()!=uid||association_path(association.GetValueOrDefault("scene_path","").AsString())!=oldPath||oldPath==newPath)continue;var updated=association.Duplicate(true);updated["scene_path"]=stored_scene_path(destination);EditAssociation(session,"Update linked scene path",updated);documents[i].AsGodotDictionary()["dirty"]=true;}}
    public string audio_saved_document_path(TabBar owner,string sourceId){int index=audio_document_index(owner,sourceId);if(index<0)return "";string path=index==Active(owner)?Workspace(owner,"audio")!.Get("document_path").AsString():Documents(owner)[index].AsGodotDictionary().GetValueOrDefault("state",new Settings()).AsGodotDictionary().GetValueOrDefault("document_path","").AsString();return path.GetExtension().ToLowerInvariant() is "tres" or "res"&&FileAccess.FileExists(path)?stored_scene_path(path):"";}
    public void new_audio(TabBar owner)=>open_audio(owner,_audioDocuments.from_source(default,""),new Settings());
    public bool open_audio(TabBar owner,Variant value,Settings binding)
    {
        var workspace=Workspace(owner,"audio");var resource=value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;bool isDocument=ActorDataOperations.ScriptIs(resource,"res://Workspaces/AudioWorkspace/KiwiAudioDocument.cs");if(workspace==null||value.VariantType!=Variant.Type.String&&resource is not AudioStream&&!isDocument)return false;string origin=owner.Get("_audio_scene_id").AsString();var documents=Documents(owner);int active=Active(owner);if(active>=0&&active<documents.Count){var current=documents[active].AsGodotDictionary();if(Kind(current)=="scene")origin=current.GetValueOrDefault("id","").AsString();else if(Kind(current)=="audio")origin=current.GetValueOrDefault("scene_id",origin).AsString();}if(binding.Count>0){binding=binding.Duplicate(true);if(binding.GetValueOrDefault("scene_id","").AsString().Length==0)binding["scene_id"]=origin;origin=binding.GetValueOrDefault("scene_id",origin).AsString();}string identity=audio_identity(value);int existing=Find(owner,"audio",identity);if(existing>=0){capture_current(owner);var document=documents[existing].AsGodotDictionary();if(document.GetValueOrDefault("id","").AsString().Length==0)document["id"]=_data.new_id();if(binding.Count>0)document["binding"]=binding;if(origin.Length>0)document["scene_id"]=origin;open_index(owner,existing);if(binding.Count>0)set_audio_scene_association(owner,document["id"].AsString(),origin,binding.GetValueOrDefault("actor_id","").AsString());return true;}string path=value.VariantType==Variant.Type.String?value.AsString():"";var initial=new Settings();if(isDocument||value.VariantType==Variant.Type.String&&path.GetExtension().ToLowerInvariant() is "tres" or "res"){var resolved=_audioWorkspace.resolve_document(value,isDocument);string error=resolved.GetValueOrDefault("error","").AsString();if(error.Length>0){workspace.Call("notice",error);return false;}var session=new KiwiAudioEditSession();_audioSessions.open(session,resolved["document"].AsGodotObject());initial=new Settings{["session"]=session,["path"]=path,["document_path"]=path};}capture_current(owner);string title=path.Length>0?path.GetFile():isDocument?resource!.Get("title").AsString():"Untitled Audio";documents.Add(new Settings{["id"]=_data.new_id(),["scene_id"]=origin,["type"]="audio",["source"]=value,["identity"]=identity,["path"]=path,["name"]=title,["state"]=initial,["binding"]=binding,["dirty"]=false});owner.Set("_switching",true);owner.AddTab(title);if(owner.TabCount>documents.Count)owner.MoveTab(owner.TabCount-1,documents.Count-1);ensure_new_tab(owner);owner.Set("_switching",false);open_index(owner,documents.Count-1);if(binding.Count>0)set_audio_scene_association(owner,documents[Active(owner)].AsGodotDictionary()["id"].AsString(),origin,binding.GetValueOrDefault("actor_id","").AsString());return true;
    }
    public void background_audio_changed(TabBar owner,RefCounted session){foreach(var value in Documents(owner)){var document=value.AsGodotDictionary();var saved=document.GetValueOrDefault("state",new Settings()).AsGodotDictionary().GetValueOrDefault("session");if(Kind(document)=="audio"&&saved.VariantType==Variant.Type.Object&&saved.AsGodotObject()==session)document["dirty"]=session.Get("dirty");}refresh_titles(owner);}
    public void active_audio_changed(TabBar owner){int index=Active(owner);var documents=Documents(owner);if(owner.Get("_switching").AsBool()||index<0||index>=documents.Count)return;var document=documents[index].AsGodotDictionary();if(Kind(document)!="audio")return;var workspace=Workspace(owner,"audio")!;document["dirty"]=workspace.Get("_dirty");workspace.Call("set_scene_binding",workspace.Get("session").AsGodotObject().Get("document").AsGodotObject().Get("scene_binding").AsGodotDictionary().Count>0);documents[index]=document;refresh_titles(owner);}
    public void audio_saved(TabBar owner,Variant value){int index=Active(owner);var documents=Documents(owner);if(index<0||index>=documents.Count)return;var document=documents[index].AsGodotDictionary();if(Kind(document)!="audio")return;string path=value.VariantType==Variant.Type.String?value.AsString():"";document["source"]=value;document["path"]=path;document["identity"]=audio_identity(value);document["name"]=path.Length>0?path.GetFile():"Audio Composition";document["dirty"]=false;documents[index]=document;refresh_titles(owner);}
    public bool open_audio_actor(TabBar owner,Resource? actor){if(actor==null||actor.Get("type_id").AsString()!="audio")return false;string path=actor.Get("values").AsGodotDictionary().GetValueOrDefault(new StringName("audio_workspace_document"),"").AsString();if(path.EnumerateRunes().Count()<=4096&&path.GetExtension().ToLowerInvariant() is "tres" or "res"&&FileAccess.FileExists(path))if(open_audio(owner,path,new Settings{["actor_id"]=actor.Get("id")}))return true;bool opened=open_audio(owner,_data.get_value(actor,"audio",default),new Settings{["actor_id"]=actor.Get("id")});if(opened&&path.Length>0)Workspace(owner,"audio")?.Call("notice","The linked editable composition could not be opened. The rendered audio was opened instead; its original source has not been changed.");return opened;}
}
